function CONDORCET_CURVATURE(P, n):
    count <- 0
    for a in 0..n-1:
      for b in 0..n-1:
        for c in 0..n-1:
          if BEATS(P,a,b) and BEATS(P,b,c) and BEATS(P,c,a):
            count <- count + 1
    return count
function BEATS(P,a,b):
    return SUPPORT(P,a,b) > SUPPORT(P,b,a)
function SUPPORT(P,a,b):
    return #{ voter r in P : rank_r(a) < rank_r(b) }

