function FLAT_FRACTION(n, k):
    R <- all n! strict rankings of n alternatives
    flat <- 0; total <- 0
    for P in R^k (all k-tuples of rankings):
        total <- total + 1
        if CONDORCET_CURVATURE(P, n) == 0: flat <- flat + 1
    return (flat, total)

